  --color-accent: hsl(210 40% 96.1%);
  /* contrast vs accent: 16.3:1 — WCAG AAA ✓ */
  --color-accent-foreground: hsl(222.2 47.4% 11.2%);

  /* EXCEPTION: destructive-foreground on destructive = 3.5:1 — WCAG AA large text only (buttons).
     Do not use --color-destructive as a small text color on white backgrounds (3.8:1, fails AA). */
  --color-destructive: hsl(0 84.2% 60.2%);
  --color-destructive-foreground: hsl(210 40% 98%);

  --color-border: hsl(214.3 31.8% 91.4%);
  --color-input: hsl(214.3 31.8% 91.4%);
  --color-ring: hsl(222.2 84% 4.9%);

  --font-sans: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, 'Noto Sans', sans-serif;

  --radius-lg: 0.5rem;
  --radius-md: calc(var(--radius-lg) - 2px);
  --radius-sm: calc(var(--radius-lg) - 4px);
}

@variant dark {
  @theme {
    --color-background: hsl(222.2 84% 4.9%);
    /* contrast vs dark background: 18.8:1 — WCAG AAA ✓ */
    --color-foreground: hsl(210 40% 98%);

    --color-card: hsl(222.2 84% 4.9%);
    /* contrast vs dark card: 18.8:1 — WCAG AAA ✓ */
    --color-card-foreground: hsl(210 40% 98%);

    --color-popover: hsl(222.2 84% 4.9%);
    /* contrast vs dark popover: 18.8:1 — WCAG AAA ✓ */
    --color-popover-foreground: hsl(210 40% 98%);

    --color-primary: hsl(210 40% 98%);
    /* contrast vs dark primary: 16.8:1 — WCAG AAA ✓ */
    --color-primary-foreground: hsl(222.2 47.4% 11.2%);

    --color-secondary: hsl(217.2 32.6% 17.5%);
    /* contrast vs dark secondary: 13.7:1 — WCAG AAA ✓ */
    --color-secondary-foreground: hsl(210 40% 98%);

    --color-muted: hsl(217.2 32.6% 17.5%);
    /* contrast vs dark background: 7.8:1, vs dark muted: 5.7:1 — WCAG AAA ✓ */
    --color-muted-foreground: hsl(215 20.2% 65.1%);

    --color-accent: hsl(217.2 32.6% 17.5%);
    /* contrast vs dark accent: 13.7:1 — WCAG AAA ✓ */
    --color-accent-foreground: hsl(210 40% 98%);

    /* destructive-foreground on dark destructive: 9.4:1 — WCAG AAA ✓ */
    --color-destructive: hsl(0 62.8% 30.6%);
    --color-destructive-foreground: hsl(210 40% 98%);

    --color-border: hsl(217.2 32.6% 17.5%);
    --color-input: hsl(217.2 32.6% 17.5%);
    --color-ring: hsl(212.7 26.8% 83.9%);
  }
}

@layer base {
  * {
    @apply border-border;
  }
  body {
    @apply bg-background text-foreground font-sans;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}
